    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 1</span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB = 4,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">(QR) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">(PR) // (BC)</span>"},{"quoi":"1)","math":"أحسب <span dir=\"ltr\" class=\"expr pt\">x = CD.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">CD.</span> نختار علاقة شال <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span> لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: AR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 2.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">CR = 2</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AC = 4</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">AC = 2 + 2</span>"},{"quoi":"في المثلّث ACD لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RQ) // (CD)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">Q ∈ (AD)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AQ</span><span class=\"den\">AD</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RQ</span><span class=\"den\">CD</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">2</span><span class=\"den\">4</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">1</span><span class=\"den\">CD</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 2</span>"},{"quoi":"2)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">y = QP.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">PQ.</span> نختار علاقة شال <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span> لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: CD = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 2.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">CD = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">BD = 2</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BC = 4</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BC = 2 + 2</span>"},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">2</span><span class=\"den\">4</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">PR</span><span class=\"den\">4</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 2</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">PR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">QR = 1</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">PQ = 1</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">PQ = 2 − 1</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">PQ = 1</span>"},{"quoi":"3)","math":"استنتج <span dir=\"ltr\" class=\"expr pt\">z = PB.</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">BP.</span> نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (PR) // (BC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">AR = 2</span>  و  <span dir=\"ltr\" class=\"expr pt\">AC = 4</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">24</span><span class=\"den\">5</span></span>. و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث ACB لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(RP) // (CB)</span>  و  <span dir=\"ltr\" class=\"expr pt\">R ∈ (AC)</span>  و  <span dir=\"ltr\" class=\"expr pt\">P ∈ (AB)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AR</span><span class=\"den\">AC</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">AB</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">RP</span><span class=\"den\">CB</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">2</span><span class=\"den\">4</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AP</span><span class=\"den\">4,8</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">AP = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AB = 4,8</span>  و  <span dir=\"ltr\" class=\"expr pt\">AP =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BP =</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">BP = 4,8 −</span> <span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BP = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">12</span><span class=\"den\">5</span></span>"}],
